{"implementation":"def solve(case):
    text = case["text"]
    passes = case["passes"]
    max_rounds = case["max_rounds"]
    applications = []
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            old = p["old"]
            new = p["new"]
            if old in text:
                text = text.replace(old, new)
                applications.append(p["name"])
                changed = True
        if not changed:
            fixed_point = True
            break
    else:
        fixed_point = False
    return {"applications": applications, "fixed_point": fixed_point, "text": text}"}
